import { Group } from 'three';

const shortName = (name) => name.split(':').pop().replace(/^mixamorig/i, '');

export function findCaster(scene) {
  const root = scene.getObjectByName('Character');
  const tilt = root?.getObjectByName('CharacterTilt');
  const model = tilt?.children.find((child) => child.isObject3D && child.children.length) ?? null;
  if (!model) return null;
  return { root, model };
}

export function findBone(model, short) {
  let found = null;
  model.traverse((node) => {
    if (!found && node.isBone && shortName(node.name) === short) found = node;
  });
  return found;
}

export function boneMap(model) {
  const bones = new Map();
  model.traverse((node) => {
    if (node.isBone) bones.set(shortName(node.name), node);
  });
  return bones;
}

/** The katana's mount without the katana: the samurai pack's prop (sword.glb) has no stated licence and is not shipped.
 *  `attach` finds no hand to mount on, so an ability's blade line falls back to its own (in front of the chest). */
export class KatanaRig {
  constructor() { this.mount = new Group(); this.mount.name = 'SamuraiKatanaMount'; this.model = null; this.bone = null; this.ready = Promise.resolve(null); }
  attach() { return false; }
  place() {}
  detach() { this.mount.parent?.remove(this.mount); this.bone = null; }
  get attached() { return false; }
}

export const KATANA_PLACEMENT = { x: -0.051, y: 0.102, z: 0.052, rotX: -168.3, rotY: 84, rotZ: -0.8, scale: 1 };
